class Solution:
    def countOperationsToEmptyArray(self, nums: List[int]) -> int:
        n = len(nums)
        bit = [0] * (n + 1)
        def upd(i, d):
            while i <= n:
                bit[i] += d
                i += i & -i
        def qry(i):
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & -i
            return s
        def kth(t):
            lo, hi = 1, n
            while lo < hi:
                mid = (lo + hi) // 2
                if qry(mid) >= t:
                    hi = mid
                else:
                    lo = mid + 1
            return lo
        for i in range(1, n + 1):
            upd(i, 1)
        ans = 0
        head = 1
        alive = n
        for val, pos in sorted(zip(nums, range(1, n + 1))):
            if pos >= head:
                steps = qry(pos) - qry(head - 1)
            else:
                steps = (qry(n) - qry(head - 1)) + qry(pos)
            ans += steps
            upd(pos, -1)
            alive -= 1
            if alive == 0:
                break
            r = qry(pos)
            head = kth(r + 1) if r < alive else kth(1)
        return ans

