class Solution {
public:
    long long countOperationsToEmptyArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> bit(n + 1, 0);
        auto upd = [&](int i, int d) { for (; i <= n; i += i & -i) bit[i] += d; };
        auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };
        auto kth = [&](int t) {
            int lo = 1, hi = n;
            while (lo < hi) { int mid = (lo + hi) / 2; if (qry(mid) >= t) hi = mid; else lo = mid + 1; }
            return lo;
        };
        for (int i = 1; i <= n; i++) upd(i, 1);
        vector<pair<int,int>> v(n);
        for (int i = 0; i < n; i++) v[i] = {nums[i], i + 1};
        sort(v.begin(), v.end());
        long long ans = 0;
        int head = 1, alive = n;
        for (auto& [val, pos] : v) {
            long long steps = (pos >= head) ? qry(pos) - qry(head - 1)
                                            : (long long)(qry(n) - qry(head - 1)) + qry(pos);
            ans += steps;
            upd(pos, -1);
            if (--alive == 0) break;
            int r = qry(pos);
            head = (r < alive) ? kth(r + 1) : kth(1);
        }
        return ans;
    }
};

