class Solution {
    public long countOperationsToEmptyArray(int[] nums) {
        int n = nums.length;
        int[] bit = new int[n + 1];
        for (int i = 1; i <= n; i++) upd(bit, i, 1);
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(nums[a], nums[b]));
        long ans = 0;
        int head = 1, alive = n;
        for (int ii : idx) {
            int pos = ii + 1;
            long steps = (pos >= head) ? qry(bit, pos) - qry(bit, head - 1)
                                       : (long)(qry(bit, n) - qry(bit, head - 1)) + qry(bit, pos);
            ans += steps;
            upd(bit, pos, -1);
            if (--alive == 0) break;
            int r = qry(bit, pos);
            head = (r < alive) ? kth(bit, n, r + 1) : kth(bit, n, 1);
        }
        return ans;
    }
    private void upd(int[] bit, int i, int d) { for (; i < bit.length; i += i & -i) bit[i] += d; }
    private int qry(int[] bit, int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }
    private int kth(int[] bit, int n, int t) {
        int lo = 1, hi = n;
        while (lo < hi) { int mid = (lo + hi) / 2; if (qry(bit, mid) >= t) hi = mid; else lo = mid + 1; }
        return lo;
    }
}

