var countOperationsToEmptyArray = function(nums) {
    const n = nums.length;
    const bit = new Array(n + 1).fill(0);
    const upd = (i, d) => { for (; i <= n; i += i & -i) bit[i] += d; };
    const qry = i => { let s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };
    const kth = t => { let lo = 1, hi = n; while (lo < hi) { const mid = (lo + hi) >> 1; if (qry(mid) >= t) hi = mid; else lo = mid + 1; } return lo; };
    for (let i = 1; i <= n; i++) upd(i, 1);
    const order = nums.map((v, i) => [v, i + 1]).sort((a, b) => a[0] - b[0]);
    let ans = 0, head = 1, alive = n;
    for (const [, pos] of order) {
        const steps = pos >= head ? qry(pos) - qry(head - 1) : (qry(n) - qry(head - 1)) + qry(pos);
        ans += steps;
        upd(pos, -1);
        if (--alive === 0) break;
        const r = qry(pos);
        head = r < alive ? kth(r + 1) : kth(1);
    }
    return ans;
};
